"""Decide evaluated candidates of one slot from their protected comparison."""

from evertree.core.programs.api import choose_candidate, compare_candidates

DESIGN = {
    "applicability": "Evaluated candidates of one slot that compare_candidates can rank.",
    "adaptation": "Each call reads fresh rankings and verification, so decisions follow evidence.",
    "learning": "Nothing is learned; changes go through the meta lifecycle with history checks.",
    "exploration": "Undecided candidates are kept open so later evidence can settle them.",
}


async def run(ctx, candidates: list):
    ranking = (await compare_candidates(ctx, candidates))["ranking"]
    status = {row["candidate"]: row["verification"]["status"] for row in ranking}
    winner = candidates[0] if status.get(candidates[0]) == "verified" else None
    decisions = {}
    for candidate in candidates:
        if candidate == winner:
            decision = "merge_branch"
        elif winner is not None:
            decision = "archive_branch"
        elif status.get(candidate) == "failed":
            decision = "reject_branch"
        else:
            decision = "continue_branch"
        await choose_candidate(ctx, candidate, decision, reason="Triage")
        decisions[candidate] = decision
    return {"result": decisions, "feedback": None}

