class Result:
    def __init__(self, value):
        self.result = value


class Ctx:
    def __init__(self, late):
        self.late, self.indexed = late, []

    async def call(self, program, arguments=None):
        return Result(self.late)

    async def step(self, method, payload=None, *, journal=True):
        self.indexed.append((method, payload))
        return []


class DeliveryNoticeTest(unittest.TestCase):
    def test_warns_only_when_late_is_likely(self):
        for late, expected in ((0.4, "warn"), (0.1, "ok")):
            ctx = Ctx(late)
            result = asyncio.run(program.run(ctx, carrier="post", parcel="X"))["result"]
            self.assertEqual(result, expected)
            self.assertEqual(ctx.indexed[0][0], "evaluation.index_forecasts")

